import type { PolarMapInstance } from '@polar/polar'

/**
 * masterportalAPI's setBackgroundImage doesn't work in nested shadow roots.
 * This solves the issue.
 */
export const setBackgroundImage = (client: PolarMapInstance) => {
	// Image source: https://geodienste.hamburg.de/lgv-config/img/backgroundCanvas.jpeg
	// Commonly used in HH by LGV
	// @ts-expect-error | It exists in our setup
	client.shadowRoot.lastElementChild.style.backgroundImage = `url('data:image/jpeg;base64,')`
}
